const routes={en:{home:'/',services:'/services/',pricing:'/pricing/',book:'/book/',join:'/join/',training:'/training/',about:'/about/',how:'/how-we-work/',trust:'/trust/',privacy:'/privacy.html',terms:'/terms/',accessibility:'/accessibility.html',resources:'/resources/',insights:'/insights/',industries:'/industries/',usecases:'/use-cases/',methodology:'/methodology/'},da:{home:'/da/',services:'/da/ydelser/',pricing:'/da/pricing/',book:'/da/book/',join:'/da/join/',training:'/da/kurser-foredrag/',about:'/da/om/',how:'/da/how-we-work/',trust:'/da/tillid/',privacy:'/da/privatliv.html',terms:'/da/terms/',accessibility:'/da/tilgaengelighed.html',resources:'/da/ressourcer/',insights:'/da/insights/',industries:'/da/brancher/',usecases:'/da/anvendelser/',methodology:'/da/metode/'},sv:{home:'/sv/',services:'/sv/tjanster/',pricing:'/sv/pricing/',book:'/sv/book/',join:'/sv/join/',training:'/sv/utbildning-forelasningar/',about:'/sv/om/',how:'/sv/how-we-work/',trust:'/sv/tillit/',privacy:'/sv/integritet.html',terms:'/sv/terms/',accessibility:'/sv/tillganglighet.html',resources:'/sv/resurser/',insights:'/sv/insights/',industries:'/sv/branscher/',usecases:'/sv/anvandningsfall/',methodology:'/sv/metod/'}};
