const organization={'@type':'Organization','@id':origin+'/#organization',name:'SundAI',legalName:'RIIMON HOLDINGS LTD',url:origin+'/',logo:origin+'/assets/sundai-wordmark-dark.svg',identifier:{'@type':'PropertyValue',propertyID:'UK company number',value:'13813344',url:registryUrl},contactPoint:{'@type':'ContactPoint',contactType:'Project enquiries',email:publicEmail,url:origin+'/book/',availableLanguage:['English','Danish','Swedish']}};
