function header(lang,alternates){const t=labels[lang],r=routes[lang];const links=['services','how','insights','guides','join'].map(k=>`<a${k==='join'?' class="network-nav"':k==='how'?' class="nav-secondary"':k==='guides'?' class="guides-nav"':''} href="${r[k]}">${esc(k==='join'?t.networkHeader:k==='faq'?seoUi[lang].faqNav:k==='buyer'?buyerCopy[lang].guideLink:t[k])}</a>`).join('');return `<a class="skip-link" href="#main">${esc(t.skip)}</a><header class="header"><div class="container header-inner"><a class="brand" href="${r.home}" aria-label="SundAI"><img src="/assets/sundai-wordmark-dark.svg" alt="SundAI" width="500" height="117"></a><nav class="desktop-nav" aria-label="${esc(t.menu)}">${links}</nav><a class="button primary" href="${r.book}">${esc(t.mobileTalk)} ↗</a><nav class="languages" aria-label="${lang==='da'?'Sprog':lang==='sv'?'Språk':'Language'}">${langs.map(l=>`<a lang="${l}" hreflang="${l}" href="${alternates[l]||routes[l].home}"${l===lang?' aria-current="page"':''}>${l.toUpperCase()}</a>`).join('')}</nav><details class="mobile-menu"><summary>${esc(t.menu)}</summary><nav aria-label="${esc(t.menu)}">${links}<a href="${r.pricing}">${esc(t.proposalShort)}</a><a href="${r.faq}">${esc(seoUi[lang].faqNav)}</a><a href="${r.training}">${esc(t.training)}</a><a href="${r.about}">${esc(t.about)}</a><a href="${r.book}">${esc(t.book)} ↗</a></nav></details></div></header>`;}
function footer(lang){const t=labels[lang],r=routes[lang];const group=(title,keys)=>`<details class="footer-nav" open><summary><h2>${esc(title)}</h2><span class="footer-toggle" aria-hidden="true"></span></summary><nav aria-label="${esc(title)}">${keys.map(k=>`<a href="${r[k]}">${esc(k==='faq'?seoUi[lang].faqNav:k==='buyer'?buyerCopy[lang].guideLink:t[k])}</a>`).join('')}</nav></details>`;return `<footer class="footer"><div class="container">${frameworkBadges(lang,r.trust)}<div class="footer-grid"><div><a href="${r.home}"><img src="/assets/sundai-wordmark-dark.svg" alt="SundAI" width="500" height="117" loading="lazy"></a><p>${esc(t.europe)}</p><p>Secure AI automation · AI governance · cybersecurity</p></div>${group(t.services,['services','pricing','book','training','join'])}${group(t.trust,['about','trust','buyer','faq','guides','resources','methodology','privacy','terms','accessibility'])}</div><div class="footer-bottom"><p>© 2026 SundAI · RIIMON HOLDINGS LTD · <a href="https://find-and-update.company-information.service.gov.uk/company/13813344" rel="external">13813344</a></p><p>${esc(t.rights)}</p></div></div></footer>`;}
function graph(lang,url,title,desc,items=[],body='',kind='page'){
 const pageUrl=origin+url;
 const serviceNodes=items.map(p=>{
  const serviceUrl=origin+(p.bundleEligible?servicePath(lang,p.id):routes[lang].pricing+'#'+p.id);
  return {'@type':'Service','@id':serviceUrl,url:serviceUrl,name:p.names[lang],serviceType:p.names[lang],description:p.scopes[lang],provider:{'@id':organization['@id']},potentialAction:{'@type':'ContactAction',target:origin+(p.bundleEligible?servicePath(lang,p.id)+'#proposal':routes[lang].book),name:labels[lang].proposalShort}};
 });
 const page={'@type':kind==='services'?'CollectionPage':'WebPage','@id':pageUrl+'#webpage',url:pageUrl,name:title,description:desc,inLanguage:lang,dateModified:pageModified(url),isPartOf:{'@id':origin+'/#website'},publisher:{'@id':organization['@id']}};
 if(kind==='service'&&serviceNodes.length===1)page.mainEntity={'@id':serviceNodes[0]['@id']};
 if(kind==='services')page.mainEntity={'@type':'ItemList',itemListElement:serviceNodes.map((item,i)=>({'@type':'ListItem',position:i+1,url:item.url,name:item.name}))};
 const questions=faqPageSchema(lang,pageUrl,body).map(item=>({...item,isPartOf:{'@id':page['@id']}}));
 return {'@context':'https://schema.org','@graph':[organization,{'@type':'WebSite','@id':origin+'/#website',url:origin+'/',name:'SundAI',inLanguage:langs,publisher:{'@id':organization['@id']}},page,{'@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:labels[lang].home,item:origin+routes[lang].home},...(url===routes[lang].home?[]:[{'@type':'ListItem',position:2,name:title,item:pageUrl}])]},...serviceNodes,...questions]};
}
function shell(lang,url,title,desc,body,alternates,kind='page',offers=[]){const t=labels[lang];body=decorateInsights(body,lang,url);return `<!doctype html>\n<html lang="${lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#050607"><meta name="sundai-content-release" content="${release}"><title>${esc(title)} | SundAI</title><meta name="description" content="${esc(desc)}"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="${origin+url}">${langs.map(l=>`<link rel="alternate" hreflang="${l}" href="${origin+(alternates[l]||routes[l].home)}">`).join('')}<link rel="alternate" hreflang="x-default" href="${origin+alternates.en}"><meta property="og:title" content="${esc(title)} | SundAI"><meta property="og:description" content="${esc(desc)}"><meta property="og:url" content="${origin+url}"><meta property="og:type" content="website"><meta property="og:image" content="${origin}/assets/sundai-brand-avatar.svg"><link rel="icon" href="/assets/sundai-brand-avatar.svg"><link rel="alternate" type="application/json" href="/discovery.json" title="SundAI service directory"><link rel="preload" href="/assets/fonts/sora-latin.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/assets/upgrade.css?v=motion-guides-20261015"><link rel="stylesheet" href="/assets/upgrade-mobile.css?v=motion-guides-20261015">${isInsightsUrl(url)?'<link rel="stylesheet" href="/assets/insights-layout.css?v=20261013">':''}<script defer src="/assets/upgrade.js?v=motion-guides-20261015"></script><script defer src="/assets/scroll-reveal.js?v=20261015"></script>${body.includes('data-testimonials')?'<script defer src="/assets/testimonials.js?v=20261015"></script>':''}${body.includes('data-lead-form')||body.includes('data-security-check')?'<script defer src="/assets/lead-growth.js"></script>':''}${body.includes('data-upgrade-form')?'<script defer src="/assets/upgrade-forms.js"></script>':''}<script type="application/ld+json" data-upgrade-schema>${JSON.stringify(graph(lang,url,title,desc,offers,body,kind)).replaceAll('<','\\u003c')}</script></head><body class="sundai-site upgrade-site" data-page-kind="${kind}">${header(lang,alternates)}<main id="main">${body}</main>${footer(lang)}<nav class="mobile-dock" aria-label="${esc(t.nextStep)}"><a href="${routes[lang].services}">${esc(t.services)}</a><a class="dock-primary" href="${kind==='service'?'#proposal':routes[lang].book}">${esc(kind==='service'?t.proposalShort:t.mobileTalk)} ↗</a></nav></body></html>\n`;}
function directCanonicalLinks(html){return html.replace(/href="(\/[^"\s]+)"/g,(full,href)=>{const u=new URL(href,origin);let target=u.pathname;const seen=new Set();while(canonicalTargets.has(target)&&!seen.has(target)){seen.add(target);target=canonicalTargets.get(target);}return target===u.pathname?full:`href="${target}${u.search}${u.hash}"`;});}
async function save(url,html){const file=path.join(root,url.endsWith('/')?url+'index.html':url);await mkdir(path.dirname(file),{recursive:true});await writeFile(file,mobileDecorations(directCanonicalLinks(html)));tracked.push(url);}
const alternates=key=>Object.fromEntries(langs.map(l=>[l,routes[l][key]]));
const buttons=lang=>`<div class="actions"><a class="button primary" href="${routes[lang].book}">${esc(labels[lang].call)} ↗</a><a class="button secondary" href="${routes[lang].services}">${esc(labels[lang].explore)}</a></div><p class="microcopy">${esc(labels[lang].micro)}</p>`;
function hero(lang,title,desc,eyebrow='SECURE AI AUTOMATION · GOVERNANCE · CYBERSECURITY'){return `<section class="page-hero"><div class="container"><p class="eyebrow">${esc(eyebrow)}</p><h1>${esc(title)}</h1><p class="lead">${esc(desc)}</p></div></section>`;}
function cards(lang,heading='h3'){const t=labels[lang];return `<div class="grid service-list">${services.map((s,i)=>{const c=s.copy[lang],x=serviceSales[s.id][lang];return `<article class="service-card"><span class="card-number">0${i+1}</span><div class="service-copy"><${heading}>${esc(c.name)}</${heading}><p class="service-benefit">${esc(serviceBenefits[s.id][lang])}</p><p>${esc(x.payoff)}</p></div><a class="card-link button secondary" href="${servicePath(lang,s.id)}">${esc(t.learn)} <span aria-hidden="true">↗</span></a></article>`;}).join('')}</div>`;}
function processSection(lang){const t=labels[lang];return `<section class="section" id="process"><div class="container"><p class="eyebrow">${esc(t.how)}</p><h2>${esc(t.processTitle)}</h2><div class="grid process-grid">${t.steps.map(([a,b],i)=>`<article class="card"><span class="card-number">0${i+1}</span><h3>${esc(a)}</h3><p>${esc(b)}</p></article>`).join('')}</div></div></section>`;}
function bundle(lang){const t=labels[lang],r=routes[lang];return `<section class="section bundle-section" id="bundle"><div class="container"><div class="band"><div><p class="eyebrow">SUNDAI / BUNDLE</p><h2>${esc(t.bundle)}</h2><p>${esc(t.bundleSub)}</p><details class="bundle-details"><summary>${esc(t.readMore)}</summary><p>${esc(t.bundleRule)}</p><p class="small">${esc(t.bundleEx)}</p></details></div><a class="button" href="${r.book}?interest=bundle">${esc(t.bundleCta)} ↗</a></div></div></section>`;}
function conditions(lang){const t=labels[lang];return `<section class="section" id="conditions"><div class="container"><h2>${esc(t.conditions)}</h2><p>${esc(t.conditionText)}</p><p>${esc(t.costs)}</p><p class="small">${esc(t.vat)}</p></div></section>`;}
function faq(lang,items=labels[lang].faqs){return `<section class="section"><div class="container"><p class="eyebrow">Q&amp;A</p><h2>${esc(seoUi[lang].faq)}</h2>${faqDetails(items,lang,servicePath)}<a class="text-link all-questions" href="${routes[lang].faq}">${esc(seoUi[lang].allQuestions)} ↗</a></div></section>`;}
function cta(lang){const t=labels[lang];return `<section class="cta"><div class="container"><p class="eyebrow">YOUR NEXT MOVE / SUNDAI</p><h2>${esc(t.final)}</h2><p>${esc(t.finalText)}</p>${buttons(lang)}</div></section>`;}
function form(lang,kind,options={}){const t=labels[lang];const input=(name,type='text',required=true,max=150)=>`<label>${esc(t[name])}<input name="${name}" type="${type}" maxlength="${max}"${required?' required':''}${name==='groupSize'?' min="1" max="10000"':''}${name==='name'?' minlength="2" autocomplete="name"':name==='email'?' autocomplete="email"':name==='organisation'?' autocomplete="organization"':''}></label>`;const select=(name,choices)=>`<label>${esc(t[name])}<select name="${name}" required>${choices.map(([value,label])=>`<option value="${esc(value)}"${options.serviceId===value?' selected':''}>${esc(label)}</option>`).join('')}</select></label>`;let extra='';if(options.serviceId)extra+=input('team','text',false,100)+input('product','text',true,150);
if(kind==='booking'||kind==='enquiry'){extra+=select('interest',[...services.map(s=>[s.id,s.copy[lang].name]),...addons.map(a=>[a.id,a.names[lang]]),['ai-decision-review','AI Decision Review'],['bundle',t.bundle],['other',t.services]])+select('language',[['English','English'],['Dansk','Dansk'],['Svenska','Svenska']]);if(kind==='booking')extra+=input('timezone')+input('preferredTime','datetime-local',true,50);}
if(kind==='join')extra=input('country')+input('language')+input('expertise')+input('experience')+input('availability')+input('portfolio','url',true,500);
if(kind==='training')extra=input('audience')+input('groupSize','number',true,10)+input('ages','text',false,100)+select('language',[['English','English'],['Dansk','Dansk'],['Svenska','Svenska']])+input('topic')+input('format')+input('dates')+input('goal');
return `<form class="data-form" data-upgrade-form data-kind="${kind}" action="/api/contact" method="post">${input('name','text',true,100)}${input('email','email',true,200)}${input('organisation','text',Boolean(options.serviceId),150)}${extra}<label class="full">${esc(t.message)}<textarea name="message" required minlength="20" maxlength="1800"${options.serviceId?` placeholder="${esc(t.proposalHint)}"`:""} rows="5" aria-describedby="form-privacy"></textarea></label><p class="full small" id="form-privacy">${esc(t.formPrivacy)}</p><div class="full" data-turnstile></div><p class="full" data-form-status role="status" aria-live="polite"></p><p class="full small">${esc(t.formNotice)} <a href="${routes[lang].privacy}">${esc(t.privacy)}</a></p><button type="submit" class="button primary">${esc(kind==='join'?t.apply:kind==='training'?t.requestWorkshop:options.serviceId?t.proposalShort:t.send)} ↗</button><p class="full small">${esc(t.fallback)} <a href="mailto:eririmo@protonmail.com">eririmo@protonmail.com</a>.</p><noscript><p class="full">${esc(t.fallback)} <a href="mailto:eririmo@protonmail.com">eririmo@protonmail.com</a>. JavaScript + Cloudflare Turnstile.</p></noscript></form>`;}
function trust(lang){const t=labels[lang],r=routes[lang];return `<section class="section"><div class="container split"><div><p class="eyebrow">${esc(t.trust)}</p><h2>${esc(t.trustTitle)}</h2><p>${esc(t.trustText)}</p><a class="button secondary" href="${r.trust}">${esc(t.trust)} ↗</a></div><div class="panel"><p>${esc(t.trustMore)}</p><p class="small">${esc(t.europe)}</p></div></div></section>`;}
function technology(lang){const t=labels[lang];return `<section class="section technology-section"><div class="container"><div class="section-heading"><div><p class="eyebrow">PLATFORMS / TOOLS</p><h2>${t.techTitle}</h2></div><p>${esc(t.techNote)}</p></div><div class="tech-groups">${['ai','cloud','security'].map(group=>`<section class="tech-group"><h3>${esc(t.techGroups[group])}</h3><div class="tech-grid">${ecosystem.filter(x=>x.group===group).map(x=>`<a data-brand="${x.id}" data-logo-kind="${x.format||'wordmark'}" class="brand-mark${x.plate===true?' light-plate':''}" href="${esc(x.url)}" rel="external">${x.src?`<img src="${esc(x.src)}" alt="${esc(x.name)}" width="180" height="64" loading="lazy">`:`<strong class="brand-wordmark">${esc(x.name)}</strong>`}<span class="brand-caption">${esc(x.name)} ↗</span></a>`).join('')}</div></section>`).join('')}</div></div></section>`;}
function network(lang){const t=labels[lang],r=routes[lang];return `<section class="section network-section" id="network"><div class="container"><div class="network-banner"><div class="network-copy"><p class="eyebrow">${esc(t.networkEyebrow)}</p><h2>${t.networkHeadline}</h2><p>${esc(t.networkBody)}</p><div class="network-actions"><a class="button primary" href="${r.join}">${esc(t.networkCta)} ↗</a><p class="network-stat">${esc(t.networkFoot)}</p></div></div><div class="network-roles"><div><h3>${esc(t.junior)}</h3>${t.juniorRoles.map(x=>`<p>${esc(x)}</p>`).join('')}</div><div><h3>${esc(t.senior)}</h3>${t.seniorRoles.map(x=>`<p>${esc(x)}</p>`).join('')}</div></div></div></div></section>`;}
function connections(lang,id){const t=connectionLabels[lang],links=serviceConnections[id];const guide=key=>{const item=guideLinks[key];const original=retained[item.path.slice(1)]||'';const target=original.match(new RegExp('hreflang="'+lang+'" href="https://sundaibot[.]com([^" ]+)"'))?.[1]||(lang==='en'?item.path:routes[lang].resources);return `<a class="resource-link" href="${target}"><span>${esc(item.labels[lang])}</span><span aria-hidden="true">↗</span></a>`;};return `<section class="section service-connections"><div class="container split"><div><h2>${esc(t.guides)}</h2><p>${esc(t.guideIntro)}</p><div class="resource-links">${links.guides.map(guide).join('')}</div></div><div><h2>${esc(t.related)}</h2><div class="resource-links">${links.related.map(other=>`<a class="resource-link" href="${servicePath(lang,other)}"><span>${esc(services.find(item=>item.id===other).copy[lang].name)}</span><span aria-hidden="true">↗</span></a>`).join('')}</div></div></div></section>`;}
const privacyCopy={en:[['Who is responsible','SundAI is operated by RIIMON HOLDINGS LTD, company number 13813344. Contact: eririmo@protonmail.com.'],['What we collect and why','We process names, work email, organisation, team/department, product/system/workflow and enquiry content to respond, assess fit and prepare requested services. Meeting requests add interest, preferred local date/time, IANA time zone and language. Freelancer applications add country/time zone, expertise, experience, availability, languages and a portfolio link. Workshop requests add audience, group size, age ranges when needed, format, dates and learning goals. Do not submit confidential records or children’s personal data.'],['Legal basis','Replying to requested enquiries and preparing a contract relies on pre-contract steps where applicable; organisational enquiries and proportionate security processing rely on legitimate interests. Marketing requires a separate choice; no marketing subscription is created by these forms.'],['Providers and international processing','Cloudflare hosts this website and runs Turnstile to prevent abuse. Our /api/contact handler sends enquiries through Resend to the operator’s configured Proton Mail inbox. Resend acceptance does not confirm inbox delivery. There is no external scheduler or database of confirmed appointments in this version. We do not use Formspree for these forms. Providers may process information outside the EU; the applicable provider processing terms and transfer safeguards must be reviewed for a specific service. European service describes service delivery by EU experts; data storage regions depend on the agreed providers and architecture.'],['Retention and access','Routine enquiries and unaccepted meeting requests are reviewed for deletion within 90 days after the last meaningful contact. Unsuccessful freelance applications are reviewed within six months; longer talent-pool retention requires a separate agreement. Contracts, tax records and relevant disputes may require longer lawful retention. Mailbox deletion is administered by the operator; this website does not automate mailbox deletion. Only authorised contributors may receive information necessary for an agreed task.'],['Your rights','Contact eririmo@protonmail.com to request access, correction, deletion, restriction, portability where applicable or to object to processing. You may complain to the supervisory authority competent for your situation. Security checks collect technical signals; do not send credentials in an enquiry.'],['Analytics and cookies','This release emits event names locally without sending names, emails, messages or portfolio links to an analytics service. No new analytics collector or marketing tracker is configured. Cloudflare security processing remains subject to its own terms.'],['Last reviewed','13 October 2026. Information in this notice describes the implemented website flow, not a certification of legal compliance.']],da:[['Ansvarlig','SundAI drives af RIIMON HOLDINGS LTD, virksomhedsnummer 13813344. Kontakt: eririmo@protonmail.com.'],['Oplysninger og formål','Vi behandler navn, arbejdsmail, organisation, team/afdeling, produkt/system/workflow og besked for at svare, vurdere samarbejde og forberede ønskede ydelser. Samtaleanmodninger tilføjer interesse, ønsket lokal tid, IANA-tidszone og sprog. Freelanceansøgninger tilføjer land/tidszone, ekspertise, erfaring, tilgængelighed, sprog og portfoliolink. Workshopanmodninger tilføjer målgruppe, størrelse, relevante aldersintervaller, format, datoer og læringsmål. Send ikke fortrolige dokumenter eller børns personoplysninger.'],['Behandlingsgrundlag','Besvarelse og kontraktforberedelse bygger, hvor relevant, på skridt før en aftale. Organisationshenvendelser og proportionale sikkerhedsforanstaltninger bygger på legitime interesser. Markedsføring kræver et særskilt valg; formularen opretter ingen abonnementer.'],['Leverandører og international behandling','Cloudflare hoster websitet og bruger Turnstile mod misbrug. /api/contact sender henvendelser gennem Resend til operatørens konfigurerede Proton Mail-indbakke. Resends accept bekræfter ikke levering til indbakken. Denne version har ingen ekstern kalender eller database over bekræftede aftaler. Formularerne bruger ikke Formspree. Leverandører kan behandle data uden for EU; relevante aftaler og overførselsgarantier vurderes for den konkrete ydelse. Europæisk service beskriver levering fra EU-eksperter; dataregioner afhænger af de aftalte leverandører og arkitektur.'],['Opbevaring og adgang','Almindelige henvendelser og ubekræftede samtaleanmodninger gennemgås med henblik på sletning inden 90 dage efter sidste væsentlige kontakt. Afviste freelanceansøgninger gennemgås inden seks måneder; længere talentpuljeopbevaring kræver særskilt aftale. Aftaler, skattebilag og tvister kan kræve længere lovlig opbevaring. Operatøren administrerer sletning i indbakken; websitet automatiserer det ikke. Kun autoriserede bidragydere modtager nødvendige oplysninger.'],['Dine rettigheder','Skriv til eririmo@protonmail.com om indsigt, rettelse, sletning, begrænsning, dataportabilitet hvor relevant eller indsigelse. Du kan klage til den kompetente tilsynsmyndighed. Sikkerhedskontrollen behandler tekniske signaler; send ikke adgangsoplysninger.'],['Analyse og cookies','Denne version udsender hændelsesnavne lokalt uden at sende navne, mails, beskeder eller portfoliolinks til en analysetjeneste. Ingen ny analyseindsamler eller marketingtracker er konfigureret. Cloudflares sikkerhedsbehandling følger deres egne vilkår.'],['Senest gennemgået','13. oktober 2026. Meddelelsen beskriver det implementerede flow; den er ikke en certificering af lovoverholdelse.']],sv:[['Ansvarig','SundAI drivs av RIIMON HOLDINGS LTD, företagsnummer 13813344. Kontakt: eririmo@protonmail.com.'],['Uppgifter och ändamål','Vi behandlar namn, arbetsmejl, organisation, team/avdelning, produkt/system/arbetsflöde och meddelande för att svara, bedöma samarbete och förbereda önskade tjänster. Samtalsförfrågningar omfattar även intresse, önskad lokal tid, IANA-tidszon och språk. Frilansansökningar omfattar land/tidszon, kompetens, erfarenhet, tillgänglighet, språk och portfoliolänk. Workshopförfrågningar omfattar målgrupp, storlek, relevanta åldersintervall, format, datum och lärandemål. Skicka inte konfidentiella dokument eller barns personuppgifter.'],['Rättslig grund','Svar och avtalsförberedelser bygger där tillämpligt på åtgärder före avtal. Organisationsförfrågningar och proportionerliga säkerhetsåtgärder bygger på berättigade intressen. Marknadsföring kräver ett separat val; formuläret skapar inga prenumerationer.'],['Leverantörer och internationell behandling','Cloudflare hostar webbplatsen och använder Turnstile mot missbruk. /api/contact skickar förfrågningar via Resend till operatörens konfigurerade Proton Mail-inkorg. Resends acceptans bekräftar inte leverans till inkorgen. Denna version har ingen extern kalender eller databas över bekräftade möten. Formulären använder inte Formspree. Leverantörer kan behandla data utanför EU; avtal och överföringsskydd bedöms för den konkreta tjänsten. Europeisk service beskriver leverans av EU-experter; dataregioner beror på avtalade leverantörer och arkitektur.'],['Lagring och åtkomst','Vanliga förfrågningar och obekräftade samtalsförfrågningar granskas för radering inom 90 dagar efter senaste meningsfulla kontakt. Avslagna frilansansökningar granskas inom sex månader; längre lagring i en talangpool kräver separat avtal. Avtal, skatteunderlag och tvister kan kräva längre laglig lagring. Operatören administrerar radering i inkorgen; webbplatsen automatiserar inte det. Endast behöriga utförare får nödvändiga uppgifter.'],['Dina rättigheter','Kontakta eririmo@protonmail.com för tillgång, rättelse, radering, begränsning, dataportabilitet där tillämpligt eller invändning. Du kan klaga till behörig tillsynsmyndighet. Säkerhetskontrollen behandlar tekniska signaler; skicka inte inloggningsuppgifter.'],['Analys och cookies','Denna version sänder händelsenamn lokalt utan att skicka namn, mejl, meddelanden eller portfoliolänkar till någon analystjänst. Ingen ny analysinsamling eller marknadsföringsspårning är konfigurerad. Cloudflares säkerhetsbehandling omfattas av deras egna villkor.'],['Senast granskad','13 oktober 2026. Informationen beskriver det implementerade flödet; den certifierar inte laglig efterlevnad.']]};
