async function walk(dir){const files=[];for(const e of await readdir(dir,{withFileTypes:true})){if(e.isDirectory()&&!['functions','tests'].includes(e.name))files.push(...await walk(path.join(dir,e.name)));else if(e.isFile()&&e.name.endsWith('.html'))files.push(path.join(dir,e.name));}return files;}
